<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const air = [[0,6],[21,6],[21,11],[23,11]];
  const pads = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],
    [15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const towerNames = ["bolt", "cannon", "frost", "lance", "flak"];
  const towers = {
    bolt:   { cost: 50,  damage: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  domains: 3 },
    cannon: { cost: 90,  damage: 60,  period: 24, range: 260, splash: 90, slow: 0,  domains: 1 },
    frost:  { cost: 70,  damage: 10,  period: 12, range: 240, splash: 0,  slow: 30, domains: 3 },
    lance:  { cost: 120, damage: 180, period: 36, range: 360, splash: 0,  slow: 0,  domains: 1 },
    flak:   { cost: 80,  damage: 40,  period: 10, range: 320, splash: 70, slow: 0,  domains: 2 }
  };
  const roster = [
    { type:"grunt",   hp:60,  speed:10, bounty:4, leak:1, air:0, first:1, weight:10 },
    { type:"runner",  hp:40,  speed:20, bounty:4, leak:1, air:0, first:2, weight:4 },
    { type:"wisp",    hp:50,  speed:12, bounty:6, leak:2, air:1, first:3, weight:3 },
    { type:"brute",   hp:150, speed:6,  bounty:9, leak:3, air:0, first:4, weight:3 },
    { type:"splitter",hp:90,  speed:8,  bounty:6, leak:2, air:0, first:6, weight:2 },
    { type:"mender",  hp:70,  speed:8,  bounty:7, leak:2, air:0, first:8, weight:1 }
  ];
  const child = { type:"splitling", speed:12, bounty:1, leak:1, air:0 };
  const slots = pads.map(([x,y],slot) => ({ slot, x:100*x+50, y:100*y+50, turret:null }));
  const strategy = createStrategy();
  const observer = createStrategy.observe;
  const log = [];
  const enemies = [];
  let queue = [];
  let gold = 250;
  let baseHp = 10;
  let wave = 0;
  let tick = 0;
  let nextId = 1;
  let fallTick = -1;
  let multiplier = 1000;

  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ''^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t;
      return (t ''^ (t >>> 14)) >>> 0;
    };
  }
  const random = mulberry32(seed);
  function compose(number) {
    const available = roster.filter(unit => unit.first <= number);
    const weight = available.reduce((total, unit) => total + unit.weight, 0);
    return Array.from({ length:4 + Math.floor(3*number/5) }, () => {
      let roll = random() % weight;
      for (const unit of available) {
        if (roll < unit.weight) return unit;
        roll -= unit.weight;
      }
    });
  }
  let preview = compose(1);

  function routeSamples(points) {
    const samples = [];
    for (let i = 1; i < points.length; i++) {
      const [x,y] = points[i-1];
      const dx = points[i][0]-x;
      const dy = points[i][1]-y;
      const length = 100*(Math.abs(dx)+Math.abs(dy));
      for (let p = 0; p < length; p++) {
        samples.push([x*100+50 + Math.sign(dx)*p, y*100+50 + Math.sign(dy)*p]);
      }
    }
    return samples;
  }
  const routes = [routeSamples(ground), routeSamples(air)];
  function position(enemy) {
    [enemy.x, enemy.y] = routes[enemy.air][enemy.progress];
  }
  function spawn(unit, number, hp, progress) {
    const armor = unit.type === "grunt" ? Math.floor(number/4) :
      unit.type === "brute" ? 6+number : 0;
    const enemy = {
      id: nextId++, type:unit.type, hp, maxHp:hp, air:unit.air, armor,
      speed:unit.speed, bounty:unit.bounty, leak:unit.leak, wave:number,
      age:0, slow:0, progress, x:0, y:0
    };
    position(enemy);
    enemies.push(enemy);
  }
  function view(enemy) {
    return {
      id:enemy.id, type:enemy.type, hp:enemy.hp, maxHp:enemy.maxHp,
      x:enemy.x, y:enemy.y, air:enemy.air, armor:enemy.armor,
      speed:enemy.speed, slowed:enemy.slow > 0,
      remaining:routes[enemy.air].length-enemy.progress
    };
  }
  function state() {
    return {
      tick, wave, gold, baseHp,
      slots:slots.map(({slot,x,y,turret}) => ({
        slot,x,y,turret:turret && { type:turret.type, tier:turret.tier, spent:turret.spent }
      })),
      enemies:enemies.map(view), nextWave:preview.map(unit => unit.type)
    };
  }
  function event(code, x, y, type, radius = 0, fromX = x, fromY = y, id = 0) {
    if (observer) observer.event({ tick, code, x, y, type, radius, fromX, fromY, id });
  }
  function apply(actions) {
    if (!Array.isArray(actions)) return;
    for (const action of actions.slice(0,32)) {
      if (!action || !Number.isInteger(action.slot) || !slots[action.slot]) continue;
      const pad = slots[action.slot];
      const turret = pad.turret;
      if (action.op === "build" && !turret && towerNames.includes(action.type)) {
        const spec = towers[action.type];
        if (gold < spec.cost) continue;
        gold -= spec.cost;
        pad.turret = { type:action.type, tier:1, spent:spec.cost, damage:spec.damage, range:spec.range, cooldown:0 };
        log.push([tick,"B",pad.slot,towerNames.indexOf(action.type)]);
        event("B",pad.x,pad.y,action.type);
      } else if (action.op === "upgrade" && turret && turret.tier < 3) {
        const cost = turret.tier * towers[turret.type].cost;
        if (gold < cost) continue;
        gold -= cost;
        turret.spent += cost;
        turret.tier++;
        turret.range += 30;
        turret.damage = Math.floor(turret.damage*16/10);
        log.push([tick,"U",pad.slot,turret.tier]);
        event("U",pad.x,pad.y,turret.type);
      } else if (action.op === "sell" && turret) {
        gold += Math.floor(turret.spent*70/100);
        pad.turret = null;
        log.push([tick,"S",pad.slot,0]);
        event("S",pad.x,pad.y,turret.type);
      }
    }
  }
  function startWave() {
    wave++;
    if (wave > 1) multiplier = Math.floor(multiplier*108/100);
    gold += Math.min(50,Math.floor(gold*5/100)) + 10 + 2*wave;
    const composition = preview;
    preview = compose(wave+1);
    event("W",1200,700,null);
    apply(strategy.plan(state()));
    composition.forEach((unit,index) => queue.push({
      unit, wave, tick:tick+4*index, index, hp:Math.floor(unit.hp*multiplier/1000)
    }));
    queue.sort((a,b) => a.tick-b.tick || a.wave-b.wave || a.index-b.index);
  }
  function within(entity, x, y, radiusSquared) {
    const dx = entity.x-x;
    const dy = entity.y-y;
    return dx*dx+dy*dy <= radiusSquared;
  }
  function fire(pad) {
    const turret = pad.turret;
    if (!turret) return;
    if (turret.cooldown > 0 && --turret.cooldown > 0) return;
    const spec = towers[turret.type];
    const candidates = enemies.filter(enemy =>
      (spec.domains & (1 << enemy.air)) && within(enemy,pad.x,pad.y,turret.range*turret.range));
    if (!candidates.length) return;
    const pick = typeof strategy.target === "function" && strategy.target(
      {slot:pad.slot,type:turret.type,tier:turret.tier,x:pad.x,y:pad.y,range:turret.range},
      candidates.map(view)
    );
    let target = candidates.find(enemy => enemy.id === pick);
    if (!target) {
      target = candidates[0];
      for (const candidate of candidates) {
        if (routes[candidate.air].length-candidate.progress < routes[target.air].length-target.progress) {
          target = candidate;
        }
      }
    }
    event("T",target.x,target.y,turret.type,spec.splash,pad.x,pad.y,target.id);
    turret.cooldown = spec.period;
    const victims = spec.splash ? enemies.filter(enemy =>
      (spec.domains & (1 << enemy.air)) && within(enemy,target.x,target.y,spec.splash*spec.splash)) : [target];
    for (const enemy of victims) {
      enemy.hp -= turret.type === "lance" ? turret.damage : Math.max(1,turret.damage-enemy.armor);
      if (spec.slow) enemy.slow = spec.slow;
    }
    const defeated = victims.filter(enemy => enemy.hp <= 0);
    for (const enemy of defeated) {
      enemies.splice(enemies.indexOf(enemy),1);
      gold += enemy.bounty;
      log.push([tick,"K",enemy.id,pad.slot]);
      event("K",enemy.x,enemy.y,enemy.type,0,enemy.x,enemy.y,enemy.id);
      if (enemy.type === "splitter") {
        const hp = Math.max(1,Math.floor(enemy.maxHp/4));
        for (let n = 0; n < 3; n++) spawn(child,enemy.wave,hp,enemy.progress);
      }
    }
  }

  for (; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick-20)%40 === 0) startWave();
    while (queue.length && queue[0].tick === tick) {
      const entry = queue.shift();
      spawn(entry.unit,entry.wave,entry.hp,0);
    }
    for (let index = 0; index < enemies.length; index++) {
      const enemy = enemies[index];
      enemy.progress += enemy.slow ? Math.floor(enemy.speed*60/100) : enemy.speed;
      if (enemy.progress >= routes[enemy.air].length) {
        baseHp -= enemy.leak;
        enemies.splice(index--,1);
        log.push([tick,"L",enemy.id,baseHp]);
        event("L",2350,1150,enemy.type,0,2350,1150,enemy.id);
        if (baseHp <= 0) {
          fallTick = tick;
          log.push([tick,"F",wave,0]);
          event("F",2350,1150,enemy.type);
          break;
        }
      } else {
        position(enemy);
      }
    }
    if (fallTick < 0) {
      for (const enemy of enemies) {
        if (++enemy.age % 20 === 0 && enemy.type === "mender") {
          event("H",enemy.x,enemy.y,enemy.type,150);
          for (const healed of enemies) {
            if (within(healed,enemy.x,enemy.y,150*150)) {
              healed.hp = Math.min(healed.maxHp,healed.hp+Math.floor(healed.maxHp*8/100));
            }
          }
        }
      }
      for (const pad of slots) fire(pad);
      for (const enemy of enemies) if (enemy.slow > 0) enemy.slow--;
    }
    if (observer) observer.frame(state());
    if (fallTick >= 0) break;
  }
  let hash = 0x811c9dc5;
  const json = JSON.stringify(log);
  for (let i = 0; i < json.length; i++) hash = Math.imul(hash ''^ json.charCodeAt(i),0x01000193);
  return {
    score:Math.round(((fallTick < 0 ? maxTicks : fallTick)-20)*100/40)/100,
    fallTick, log, hash:(hash >>> 0).toString(16).padStart(8,"0")
  };
}
