    1.659,1.622,1.029,1.650,1.270,.947,1.004,.262];
  const tierWeight = [1,.722,.519];
  let recentWisps = 1;

  function preferredType(slot,wave) {
    if (slot === 2 && wave < 7) return 0;
    if (slot === 10 && wave < 33) return 3;
    return layout[slot];
  }

  return {
    plan(state) {
      const actions = [];
      let gold = state.gold;
      const pads = state.slots.map(({slot,turret}) => ({
        slot, tier:turret?.tier || 0, spent:turret?.spent || 0,
        current:turret ? types.indexOf(turret.type) : -1, desired:preferredType(slot,state.wave)
      }));
      const flyers = state.nextWave.filter(type => type === \"wisp\").length;
      recentWisps = .8*recentWisps + .2*flyers;
      const antiAirValue = state.wave < 3 && flyers === 0 ? .13 :
        Math.min(1.45,.72+.1*recentWisps+.06*flyers);

      while (actions.length < 28) {
        let choice = null;
        let bestValue = 0;
        for (const pad of pads) {
          const {slot,tier,current,desired,spent} = pad;
          const swap = tier > 0 && current "'!== desired;
          if (tier === 3 && !swap) continue;
          const price = swap ? cost[desired]-Math.floor(spent*70/100) : cost[desired]*Math.max(1,tier);
          if (price > gold) continue;
          let value = investment[slot];
          // Reserve a frost position for slowing flyers and a lance for armoured units.
          if (!tier && state.wave >= 17 && slot === 15) value = Math.max(.94,value);
          if (!tier && state.wave >= 17 && slot === 10) value = Math.max(1.4,value);
          value *= swap ? 1.8 : tierWeight[tier];
          if (desired === 4) value *= antiAirValue;
          if (!tier && state.wave === 1) {
            if (slot === 0) value *= 4;
            if (slot === 2) value *= 2;
          }
          if (value > bestValue) {
            bestValue = value;
            choice = {pad,swap,price};
          }
        }
        if (!choice) break;
        const {pad,swap,price} = choice;
        if (swap) {
          actions.push({op:"sell",slot:pad.slot});
          pad.tier = 0;
          pad.spent = 0;
        }
        if (pad.tier) {
          actions.push({op:"upgrade",slot:pad.slot});
          pad.spent += cost[pad.current]*pad.tier;
        } else {
          pad.current = pad.desired;
          pad.spent = cost[pad.desired];
          actions.push({op:"build",slot:pad.slot,type:types[pad.desired]});
        }
        pad.tier++;
        gold -= price;
      }
      return actions;
    },

    target(turret,candidates) {
